<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Notification Center V12.16 — targeted categories, priority and unread intelligence */
function tuff_beatz_notifications($id){$v=get_post_meta((int)$id,'_tb_notifications_v9',true);return is_array($v)?array_values($v):array();}
function tuff_beatz_notification_taxonomy(){return array('message'=>array('category'=>'communication','priority'=>'normal'),'status'=>array('category'=>'workflow','priority'=>'normal'),'payment'=>array('category'=>'commerce','priority'=>'high'),'approval'=>array('category'=>'review','priority'=>'high'),'review'=>array('category'=>'review','priority'=>'normal'),'delivery'=>array('category'=>'delivery','priority'=>'critical'),'file'=>array('category'=>'assets','priority'=>'normal'),'system'=>array('category'=>'system','priority'=>'low'));}
function tuff_beatz_notification_enrich($item){$type=sanitize_key($item['type']??'system');$tax=tuff_beatz_notification_taxonomy();$cfg=$tax[$type]??array('category'=>'project','priority'=>'normal');$item['type']=$type;$item['category']=sanitize_key($item['category']??$cfg['category']);$item['priority']=sanitize_key($item['priority']??$cfg['priority']);return $item;}
function tuff_beatz_notification_recipients($id){$out=array();$p=get_post($id);if($p&&$p->post_author){$u=get_userdata($p->post_author);if($u&&is_email($u->user_email))$out[$u->ID]=$u->user_email;}if(function_exists('tuff_beatz_project_collaborators'))foreach(tuff_beatz_project_collaborators($id) as $c){$uid=(int)($c['user_id']??0);$email=sanitize_email($c['email']??'');if($uid&&$email)$out[$uid]=$email;}return $out;}
function tuff_beatz_notification_visible_to($item,$uid=0){$uid=$uid?:get_current_user_id();$targets=array_map('intval',(array)($item['recipient_ids']??array()));return !$targets||in_array((int)$uid,$targets,true);}
function tuff_beatz_notification_project_producers($id,$exclude=0){$out=array();foreach(get_users(array('fields'=>array('ID','user_email','display_name'))) as $u){if((int)$u->ID===(int)$exclude)continue;if(user_can($u->ID,'edit_post',(int)$id)&&is_email($u->user_email))$out[(int)$u->ID]=$u->user_email;}return $out;}
function tuff_beatz_notification_project_clients($id,$exclude=0){$out=tuff_beatz_notification_recipients($id);if($exclude)unset($out[(int)$exclude]);foreach(array_keys($out) as $uid)if(user_can((int)$uid,'edit_post',(int)$id))unset($out[$uid]);return $out;}
function tuff_beatz_notification_store($id,$item){$n=tuff_beatz_notifications($id);$n[]=tuff_beatz_notification_enrich($item);if(count($n)>200)$n=array_slice($n,-200);update_post_meta($id,'_tb_notifications_v9',$n);return end($n);}
function tuff_beatz_add_notification($id,$type,$title,$message,$email=true,$priority=''){$id=(int)$id;if(!$id||get_post_type($id)!=='tb_request')return false;$item=tuff_beatz_notification_enrich(array('id'=>wp_generate_uuid4(),'type'=>$type,'title'=>sanitize_text_field($title),'message'=>sanitize_text_field($message),'time'=>current_time('mysql'),'read_by'=>array()));if($priority)$item['priority']=sanitize_key($priority);$item=tuff_beatz_notification_store($id,$item);if(function_exists('tuff_beatz_add_activity'))tuff_beatz_add_activity($id,'notification',$title);if($email){$subject='TUFF BEATZ — '.$title;$body=$message."\n\nProject: ".get_the_title($id)."\nOpen your project: ".(function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($id):home_url('/client-portal/'))."\n\nTUFF BEATZ — SOUND. PURPOSE. LEGACY.";foreach(array_unique(tuff_beatz_notification_recipients($id)) as $to)wp_mail($to,$subject,$body);}return $item;}
function tuff_beatz_add_targeted_notification($id,$type,$title,$message,$recipient_map,$sender_id=0,$email=true,$priority=''){$id=(int)$id;if(!$id||get_post_type($id)!=='tb_request')return false;$recipient_map=is_array($recipient_map)?$recipient_map:array();$recipient_ids=array_values(array_unique(array_filter(array_map('intval',array_keys($recipient_map)))));if(!$recipient_ids)return false;$item=tuff_beatz_notification_enrich(array('id'=>wp_generate_uuid4(),'type'=>$type,'title'=>sanitize_text_field($title),'message'=>sanitize_text_field($message),'time'=>current_time('mysql'),'read_by'=>$sender_id?array((int)$sender_id):array(),'recipient_ids'=>$recipient_ids,'sender_id'=>(int)$sender_id));if($priority)$item['priority']=sanitize_key($priority);$item=tuff_beatz_notification_store($id,$item);if(function_exists('tuff_beatz_add_activity'))tuff_beatz_add_activity($id,'notification',$title,$sender_id?:get_current_user_id());if($email){$subject='TUFF BEATZ — '.$title;$url=(function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($id):home_url('/client-portal/')).($type==='message'?'#messages':'#notifications');$body=$message."\n\nProject: ".get_the_title($id)."\nOpen your project: ".$url."\n\nTUFF BEATZ — SOUND. PURPOSE. LEGACY.";foreach(array_unique(array_filter(array_map('sanitize_email',array_values($recipient_map)))) as $to)if(is_email($to))wp_mail($to,$subject,$body);}return $item;}
function tuff_beatz_notification_unread($id,$uid=0,$category=''){$uid=$uid?:get_current_user_id();$count=0;foreach(tuff_beatz_notifications($id) as $raw){$x=tuff_beatz_notification_enrich($raw);if(!tuff_beatz_notification_visible_to($x,$uid))continue;if($category&&$x['category']!==$category)continue;if(!in_array((int)$uid,array_map('intval',(array)($x['read_by']??array())),true))$count++;}return $count;}
function tuff_beatz_notify_project_message($id,$sender_id,$sender_name,$sender_type,$body='',$attachment_count=0){$sender_type=$sender_type==='producer'?'producer':'client';$recipients=$sender_type==='producer'?tuff_beatz_notification_project_clients($id,$sender_id):tuff_beatz_notification_project_producers($id,$sender_id);if(!$recipients)return false;$preview=trim(preg_replace('/\s+/',' ',wp_strip_all_tags((string)$body)));if(strlen($preview)>150)$preview=substr($preview,0,147).'...';if(!$preview&&$attachment_count)$preview=$attachment_count.' secure attachment'.($attachment_count===1?'':'s').' added.';$title=$sender_type==='producer'?'New Message from TUFF BEATZ':'New Client Message';return tuff_beatz_add_targeted_notification($id,'message',$title,($sender_name?:'Project Member').' sent a project message'.($preview?': '.$preview:'.'),$recipients,$sender_id,true,'normal');}
function tuff_beatz_notify_status_change($meta_id,$object_id,$meta_key,$meta_value){if(get_post_type($object_id)!=='tb_request')return;if($meta_key==='_tb_request_status'){static $busy=false;if($busy)return;$busy=true;$labels=function_exists('tuff_beatz_request_status_label')?tuff_beatz_request_status_label($meta_value):ucwords(str_replace('-',' ',$meta_value));$map=array('reviewing'=>array('Project Review Started','normal'),'approved'=>array('Project Approved','normal'),'in-progress'=>array('Production Started','normal'),'revision'=>array('Revision Stage','normal'),'mastering'=>array('Mastering Started','high'),'delivery'=>array('Final Delivery Ready','critical'),'completed'=>array('Project Completed','high'),'declined'=>array('Project Status Updated','high'));if(isset($map[$meta_value]))tuff_beatz_add_notification($object_id,$meta_value==='delivery'?'delivery':'status',$map[$meta_value][0],'Your project status is now '.$labels.'.',true,$map[$meta_value][1]);$busy=false;}if($meta_key==='_tb_request_payment_status'){static $paybusy=false;if($paybusy)return;$paybusy=true;$s=(string)$meta_value;$map=array('Deposit due'=>array('Deposit Is Due','high'),'Balance due'=>array('Balance Payment Is Due','high'),'Paid in full'=>array('Payment Complete','normal'));if(isset($map[$s]))tuff_beatz_add_notification($object_id,'payment',$map[$s][0],$s==='Paid in full'?'Your project is paid in full. Thank you.':'A payment action is ready in your project workspace.',true,$map[$s][1]);$paybusy=false;}}
add_action('added_post_meta','tuff_beatz_notify_status_change',20,4);add_action('updated_post_meta','tuff_beatz_notify_status_change',20,4);
function tuff_beatz_notification_mix_meta($meta_id,$object_id,$meta_key,$meta_value){if(get_post_type($object_id)==='tb_request'&&$meta_key==='_tb_approved_mix_file')tuff_beatz_add_notification($object_id,'approval','Mix Approved','The approved mix has moved forward to mastering.',true,'high');}add_action('added_post_meta','tuff_beatz_notification_mix_meta',25,4);add_action('updated_post_meta','tuff_beatz_notification_mix_meta',25,4);
function tuff_beatz_mark_notifications_read(){$id=(int)($_POST['request_id']??0);$r=function_exists('tuff_beatz_project_dashboard_url')?tuff_beatz_project_dashboard_url($id):home_url('/client-portal/');if(!is_user_logged_in()||!function_exists('tuff_beatz_user_project_permission')||!tuff_beatz_user_project_permission($id,'view')){wp_safe_redirect($r);exit;}if(!isset($_POST['tb_notify_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tb_notify_nonce'])),'tb_notify_'.$id)){wp_safe_redirect($r);exit;}$uid=get_current_user_id();$n=tuff_beatz_notifications($id);foreach($n as &$x){if(!tuff_beatz_notification_visible_to($x,$uid))continue;$read=array_map('intval',(array)($x['read_by']??array()));if(!in_array($uid,$read,true))$read[]=$uid;$x['read_by']=$read;}unset($x);update_post_meta($id,'_tb_notifications_v9',$n);wp_safe_redirect($r.'#notifications');exit;}add_action('admin_post_tb_mark_notifications_read','tuff_beatz_mark_notifications_read');
function tuff_beatz_render_notifications_workspace(){if(!is_page('project-dashboard')||!is_user_logged_in())return;$id=(int)($_GET['project']??0);if(!$id||!function_exists('tuff_beatz_user_project_permission')||!tuff_beatz_user_project_permission($id,'view'))return;$uid=get_current_user_id();$all=array();foreach(array_reverse(tuff_beatz_notifications($id)) as $raw){$x=tuff_beatz_notification_enrich($raw);if(tuff_beatz_notification_visible_to($x,$uid))$all[]=$x;}$unread=tuff_beatz_notification_unread($id,$uid);echo '<template id="tb-notifications-template"><section id="notifications" class="tb-portal-card tb-workspace-section tb-notifications"><div class="tb-notify-head"><div><p class="tb-card-kicker">NOTIFICATION CENTER V12.16</p><h2>Project Alerts</h2></div><span>'.esc_html($unread).' unread</span></div><div class="tb-notify-filters"><button type="button" class="is-active" data-category="all">ALL</button><button type="button" data-category="communication">MESSAGES</button><button type="button" data-category="workflow">WORKFLOW</button><button type="button" data-category="review">REVIEW</button><button type="button" data-category="commerce">PAYMENTS</button><button type="button" data-category="delivery">DELIVERY</button></div>';if($all){echo '<div class="tb-notify-list">';foreach(array_slice($all,0,60) as $x){$isread=in_array($uid,array_map('intval',(array)($x['read_by']??array())),true);echo '<article data-category="'.esc_attr($x['category']).'" class="tb-notify-item tb-priority-'.esc_attr($x['priority']).($isread?' is-read':' is-unread').'"><i></i><div><small>'.esc_html(strtoupper($x['category'].' • '.$x['priority'])).'</small><h3>'.esc_html($x['title']??'Project Update').'</h3><p>'.esc_html($x['message']??'').'</p><span>'.esc_html(mysql2date('M j, Y g:i a',$x['time']??'')).'</span></div></article>';}echo '</div><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="tb-notify-read"><input type="hidden" name="action" value="tb_mark_notifications_read"><input type="hidden" name="request_id" value="'.esc_attr($id).'">';wp_nonce_field('tb_notify_'.$id,'tb_notify_nonce');echo '<button class="btn btn-outline" type="submit">Mark All Read</button></form>';}else echo '<p class="tb-empty-state">No notifications yet. Important project updates will appear here.</p>';echo '</section></template><script>document.addEventListener("DOMContentLoaded",function(){var t=document.getElementById("tb-notifications-template"),m=document.getElementById("messages"),nav=document.querySelector(".tb-dashboard-nav");if(t&&m)m.parentNode.insertBefore(t.content.cloneNode(true),m);var s=document.getElementById("notifications");if(s)s.querySelectorAll(".tb-notify-filters button").forEach(function(b){b.addEventListener("click",function(){s.querySelectorAll(".tb-notify-filters button").forEach(function(x){x.classList.remove("is-active")});b.classList.add("is-active");s.querySelectorAll(".tb-notify-item").forEach(function(x){x.hidden=b.dataset.category!=="all"&&x.dataset.category!==b.dataset.category;});});});if(nav){var a=document.createElement("a");a.href="#notifications";a.textContent="Notifications'.($unread?' ('.(int)$unread.')':'').'";var x=nav.querySelector("a[href=\"#messages\"]");if(x)nav.insertBefore(a,x);else nav.appendChild(a);}});</script>';}add_action('wp_footer','tuff_beatz_render_notifications_workspace',6);
function tuff_beatz_notifications_assets(){if(is_page(array('project-dashboard','client-portal','producer-portal'))){$p=get_template_directory().'/assets/css/notifications.css';if(file_exists($p))wp_enqueue_style('tuff-beatz-notifications',get_template_directory_uri().'/assets/css/notifications.css',array('tuff-beatz-project-portal'),filemtime($p));wp_add_inline_style('tuff-beatz-notifications','.tb-notify-filters{display:flex;gap:6px;flex-wrap:wrap;margin:14px 0}.tb-notify-filters button{border:1px solid rgba(255,255,255,.07);border-radius:999px;background:transparent;color:#777166;padding:6px 9px;font-size:.54rem;letter-spacing:.08em;cursor:pointer}.tb-notify-filters button.is-active{border-color:rgba(216,180,90,.32);color:#e4c66f;background:rgba(216,180,90,.06)}.tb-notify-item.tb-priority-critical{border-color:rgba(216,180,90,.35)}.tb-notify-item.tb-priority-critical>i{box-shadow:0 0 0 4px rgba(216,180,90,.08)}');}}add_action('wp_enqueue_scripts','tuff_beatz_notifications_assets',48);
